sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
async function handler({api, event, helpers, imports}) {
    debugger;
    const tableName = api.state.tableName;
    const tableSysId = api.state.tableSysId;
    const file = api.state.uploadFileObject;
    const url = `/api/now/attachment/file?table_name=${encodeURIComponent(tableName)}&table_sys_id=${encodeURIComponent(tableSysId)}&file_name=${encodeURIComponent(file.name)}`;
    console.debug(">>>>>API URL=" + url);

    var attachmentSysId;

    /**
        {response}としないと、response.response.resultになるため
    */
    const {
        response
    } = await helpers.snHttp(url, {
        method: "POST",
        headers: {
            "Content-Type": file.type || 'application/octet-stream',
            'Accept': "application/json"
        },
        body: file,
        credentials: "include"
    });

    if (!response.result) {
        throw new Error("Upload failed: " + response.status);
    }
    attachmentSysId = response.result.sys_id;
    console.debug(">>>>>Attachemnt sysID=" + attachmentSysId);

    // SysIdを設定すると、しばらくしたらGet Excel DataがFetchされる
    api.setState("attachmentSysId", attachmentSysId);
// debugger;
    // Mutateに変更したための検証
    // var ret = await api.data.get_excel_data.execute({sys_id: attachmentSysId});


}
